<?php
require __DIR__.'/common.php';
bridge_run('POST',function(PDO $db,array $device):array{$body=bridge_body();if(($body['device_serial']??'')!==$device['values']['device_code'])throw new InvalidArgumentException('Token belongs to a different device.');$online=($body['device_online']??false)===true?1:0;$last=empty($body['last_device_timestamp'])?null:chr_datetime($body['last_device_timestamp']);$error=ftext($body,'error',500);$db->prepare('INSERT INTO hr_bridge_health(device_id,last_seen,device_online,last_device_timestamp,last_error) VALUES(?,NOW(),?,?,?) ON DUPLICATE KEY UPDATE last_seen=NOW(),device_online=VALUES(device_online),last_device_timestamp=VALUES(last_device_timestamp),last_error=VALUES(last_error)')->execute([$device['id'],$online,$last,$error]);foreach(['sync_requested_at','test_requested_at'] as $key)if(!empty($body['ack_commands'][$key]))$db->prepare('UPDATE hr_bridge_health SET '.$key.'=NULL WHERE device_id=? AND '.$key.'=?')->execute([$device['id'],$body['ack_commands'][$key]]);return ['ok'=>true];});
